base-permit:
@id("base-permit")
permit (principal, action, resource is AgentCore::Gateway)
when {
  principal.hasTag("sub") &&
  (principal.getTag("sub") == "{{AGENT_SUB}}" || principal.getTag("sub") == "{{EXECUTOR_SUB}}")
};

rule_default_spend:
@id("rule_default_spend")
forbid (
  principal,
  action in [AgentCore::Action::"Supplies___checkout", AgentCore::Action::"Services___book_service"],
  resource == AgentCore::Gateway::"{{GATEWAY_ARN}}"
)
when {
  principal.hasTag("sub") && principal.getTag("sub") == "{{AGENT_SUB}}" &&
  context has input && context.input has amount_minor && context.input.amount_minor > 5000
};

rule_default_contacts:
@id("rule_default_contacts")
forbid (
  principal,
  action == AgentCore::Action::"Messages___send_email",
  resource == AgentCore::Gateway::"{{GATEWAY_ARN}}"
)
when {
  principal.hasTag("sub") && principal.getTag("sub") == "{{AGENT_SUB}}" &&
  context has input && context.input has recipient_email
};

rule_default_calendar:
@id("rule_default_calendar")
forbid (
  principal,
  action in [AgentCore::Action::"Calendar___update_event", AgentCore::Action::"Calendar___delete_event"],
  resource == AgentCore::Gateway::"{{GATEWAY_ARN}}"
)
when {
  context has input && context.input has event_owner && context.input.event_owner == "human"
};

rule_default_services:
@id("rule_default_services")
forbid (
  principal,
  action == AgentCore::Action::"Services___book_service",
  resource == AgentCore::Gateway::"{{GATEWAY_ARN}}"
)
when {
  principal.hasTag("sub") && principal.getTag("sub") == "{{AGENT_SUB}}"
};

rule_default_refunds:
@id("rule_default_refunds")
forbid (
  principal,
  action == AgentCore::Action::"Supplies___refund",
  resource == AgentCore::Gateway::"{{GATEWAY_ARN}}"
)
when {
  principal.hasTag("sub") && principal.getTag("sub") == "{{AGENT_SUB}}"
};
